import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.io.IOException;
import java.io.InputStream;
import java.util.Iterator;

@Path("/druid/indexer/v1/sampler")
public class SamplerResource
{
  private final ObjectMapper jsonMapper;

  @Inject
  public SamplerResource(@Json ObjectMapper jsonMapper)
  {
    this.jsonMapper = jsonMapper;
  }

  @POST
  @Consumes(MediaType.APPLICATION_JSON)
  @Produces(MediaType.APPLICATION_JSON)
  @ResourceFilters(StateResourceFilter.class)
  public Response post(final InputStream body)
  {
    try {
      final JsonNode rootNode = jsonMapper.readTree(body);
      Preconditions.checkNotNull(rootNode, "Request body cannot be empty");
      rejectEmptyKeys(rootNode);
      final SamplerSpec sampler = jsonMapper.treeToValue(rootNode, SamplerSpec.class);
      Preconditions.checkNotNull(sampler, "Request body cannot be empty");
      return Response.ok(sampler.sample()).build();
    }
    catch (SamplerException e) {
      throw e;
    }
    catch (IllegalArgumentException e) {
      throw e;
    }
    catch (IOException e) {
      throw new SamplerException(e, "Failed to parse sampler request: %s", e.getMessage());
    }
  }

  /**
   * Recursively validates that no JSON object in the tree contains an empty string key "".
   *
   * Jackson's @JacksonInject mechanism uses the empty string as the default inject key.
   * A payload containing {"": {"enabled": true}} can override injected JavaScriptConfig,
   * bypassing the JavaScript-disabled security check and enabling arbitrary code execution.
   */
  private void rejectEmptyKeys(final JsonNode node)
  {
    if (node.isObject()) {
      final Iterator<String> fieldNames = node.fieldNames();
      while (fieldNames.hasNext()) {
        final String fieldName = fieldNames.next();
        if (fieldName.isEmpty()) {
          throw new SamplerException(
              null,
              "Request contains an empty string key which is not allowed"
          );
        }
        rejectEmptyKeys(node.get(fieldName));
      }
    } else if (node.isArray()) {
      for (final JsonNode child : node) {
        rejectEmptyKeys(child);
      }
    }
  }
}

